package com.college.events.controller;
import com.college.events.dto.ReadinessDtos; import com.college.events.model.Event; import com.college.events.repository.FacilityBookingRepository; import com.college.events.repository.VolunteerMembershipRepository; import com.college.events.repository.VolunteerTaskRepository; import com.college.events.security.DomainAccess; import com.college.events.service.EventOperationsService; import com.college.events.service.FeatureFlagService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/cujammu/readiness") @RequiredArgsConstructor
public class ReadinessApiController { private final FacilityBookingRepository bookings; private final EventOperationsService operations; private final DomainAccess access; private final FeatureFlagService flags; private final VolunteerMembershipRepository memberships; private final VolunteerTaskRepository volunteerTasks;
 @GetMapping("/events/{eventId}") public ReadinessDtos.View view(@PathVariable long eventId){flags.requireEnabledForRead("MODULE_READINESS"); Event e=access.requireEventManager(eventId);var checks=new ArrayList<ReadinessDtos.Check>(); checks.add(new ReadinessDtos.Check("APPROVAL","Event approved",e.getStatus().name().equals("APPROVED"),e.getStatus().name())); try{var o=operations.view(eventId);checks.add(new ReadinessDtos.Check("OPERATIONS","Operations workspace initialized",o.revision()>=0,o.revision()<0?"Initialize operations":"Ready"));checks.add(new ReadinessDtos.Check("ATTENDANCE_POLICY","Attendance mode configured",o.attendanceMode()!=null&&!o.attendanceMode().isBlank(),!Objects.toString(o.attendanceMode(),"").isBlank()?o.attendanceMode():"Missing"));}catch(RuntimeException ex){checks.add(new ReadinessDtos.Check("OPERATIONS","Operations workspace initialized",false,"Unavailable"));checks.add(new ReadinessDtos.Check("ATTENDANCE_POLICY","Attendance mode configured",false,"Unavailable"));}
  try { var linked=bookings.findActiveByEventIdOrderByStartTimeAsc(eventId); boolean confirmed=!linked.isEmpty()&&linked.stream().allMatch(b->"CONFIRMED".equals(b.getStatus())); boolean pending=linked.stream().anyMatch(b->"PENDING".equals(b.getStatus())); String detail=confirmed?"All linked active facility bookings are confirmed":pending?"At least one facility booking awaits review":"No active linked facility booking evidence"; checks.add(new ReadinessDtos.Check("RESOURCE_CONFIRMATION","Facility resource confirmation",confirmed,detail)); }
  catch(RuntimeException ex){checks.add(new ReadinessDtos.Check("RESOURCE_CONFIRMATION","Facility resource confirmation",false,"Unavailable"));}
  try { long accepted=memberships.countEligibleAcceptedByEventId(eventId); long unassigned=volunteerTasks.countByEventIdAndStatus(eventId,"PENDING"); long open=volunteerTasks.countByEventIdAndStatusIn(eventId,List.of("PENDING","ASSIGNED","IN_PROGRESS")); checks.add(new ReadinessDtos.Check("VOLUNTEER_COVERAGE","Volunteer roster and shift evidence",false,"Informational only: "+accepted+" accepted verified volunteer(s); "+open+" open volunteer task(s) ("+unassigned+" unassigned). No approved staffing/referee target or shift-availability evidence is configured.")); }
  catch(RuntimeException ex){checks.add(new ReadinessDtos.Check("VOLUNTEER_COVERAGE","Volunteer roster and shift evidence",false,"Unavailable; staffing coverage is not verified."));}
  checks.add(new ReadinessDtos.Check("READINESS_SCOPE","Complete operational readiness evidence",false,
          "Staffing, accessibility, emergency contact, handover, and waitlist checks are not yet available; this summary cannot certify the event ready."));
  return new ReadinessDtos.View(eventId,e.getStatus().name(),checks.stream().allMatch(ReadinessDtos.Check::passed),checks); }
}
